import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [a, m] = input[0].split(" ").map(BigInt);

// 拡張ユークリッドの互除法: a*s ≡ r (mod m) を保ちながら r を小さくしていく
let [oldR, r] = [a % m, m];
let [oldS, s] = [1n, 0n];
while (r !== 0n) {
  const q = oldR / r;
  [oldR, r] = [r, oldR - q * r];
  [oldS, s] = [s, oldS - q * s];
}

// oldR は gcd(a, m)。1 でなければ逆数は存在しない
if (oldR !== 1n) console.log("-1");
else console.log((((oldS % m) + m) % m).toString());
